import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container for this node
  const root = new Group();

  // Plane geometry – size will be controlled by the adapter via scenePosition/scale
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();

  // Gradient color (ink → paper) based on vertical UV coordinate
  const inkNode = color('#16161d');
  const paperNode = color('#e8ecf2');
  material.colorNode = mix(inkNode, paperNode, uv().y);

  // Load texture asynchronously; assign when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Event handlers placeholder (none defined for this node)
  root.userData.handlers = {};

  // Cleanup routine: dispose geometry, material, and any GSAP timelines
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // No timelines were created, but ensure any future ones are killed
    if (root.userData._timelines) {
      root.userData._timelines.forEach((tl) => tl.kill());
    }
  };

  return root;
}
